ALTER TABLE public.site_settings ADD COLUMN IF NOT EXISTS color_mode text NOT NULL DEFAULT 'dark', ADD COLUMN IF NOT EXISTS background_color text, ADD COLUMN IF NOT EXISTS hero_image_url text, ADD COLUMN IF NOT EXISTS homepage_sections jsonb NOT NULL DEFAULT '["featured","trending","recent","downloads","views","copies","games","categories"]'::jsonb, ADD COLUMN IF NOT EXISTS custom_css text, ADD COLUMN IF NOT EXISTS other_social_url text;
ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS icon text NOT NULL DEFAULT 'Megaphone', ADD COLUMN IF NOT EXISTS link_url text, ADD COLUMN IF NOT EXISTS start_at timestamptz, ADD COLUMN IF NOT EXISTS end_at timestamptz;
CREATE OR REPLACE FUNCTION public.protect_profile_fields() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.has_role(auth.uid(), 'admin') THEN IF NEW.is_banned IS DISTINCT FROM OLD.is_banned OR NEW.is_disabled IS DISTINCT FROM OLD.is_disabled THEN RAISE EXCEPTION 'Account status can only be changed by an administrator'; END IF; END IF; IF auth.role() IS DISTINCT FROM 'service_role' AND NEW.avatar_url IS DISTINCT FROM OLD.avatar_url THEN RAISE EXCEPTION 'Use moderated avatar upload'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_profile_fields_before_update BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_fields();
CREATE POLICY "staff list site media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admins upload site media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admins update site media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admins delete site media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));